82	fn setsockopt<V: Sized>(
83	    fd: RawFd,
84	    level: libc::c_int,
85	    name: libc::c_int,
86	    value: &V,
87	) -> Result<(), io::Error> {
88	    let res = unsafe {
89	        libc::setsockopt(
90	            fd,
91	            level,
92	            name,
93	            mem::transmute(value),
94	            mem::size_of_val(value).try_into().unwrap(),
95	        )
96	    };
97	    if res == 0 {
98	        Ok(())
99	    } else {
100	        Err(io::Error::new(
101	            io::ErrorKind::Other,
102	            format!("Failed to set sockopt (res = {}, errno = {})", res, errno()),
103	        ))
104	    }
105	}
