132	impl Endpoint for LinuxEndpoint {
133	    fn from_address(addr: SocketAddr) -> Self {
134	        match addr {
135	            SocketAddr::V4(addr) => LinuxEndpoint::V4(EndpointV4 {
136	                dst: libc::sockaddr_in {
137	                    sin_family: libc::AF_INET as libc::sa_family_t,
138	                    sin_port: addr.port().to_be(),
139	                    sin_addr: libc::in_addr {
140	                        s_addr: u32::from(*addr.ip()).to_be(),
141	                    },
142	                    sin_zero: [0; 8],
143	                },
144	                info: libc::in_pktinfo {
145	                    ipi_ifindex: 0,                            // interface (0 is via routing table)
146	                    ipi_spec_dst: libc::in_addr { s_addr: 0 }, // src IP (dst of incoming packet)
147	                    ipi_addr: libc::in_addr { s_addr: 0 },
148	                },
149	            }),
150	            SocketAddr::V6(addr) => LinuxEndpoint::V6(EndpointV6 {
151	                dst: libc::sockaddr_in6 {
152	                    sin6_family: libc::AF_INET6 as libc::sa_family_t,
153	                    sin6_port: addr.port().to_be(),
154	                    sin6_flowinfo: addr.flowinfo(),
155	                    sin6_addr: libc::in6_addr {
156	                        s6_addr: addr.ip().octets(),
157	                    },
158	                    sin6_scope_id: addr.scope_id(),
159	                },
160	                info: libc::in6_pktinfo {
161	                    ipi6_addr: libc::in6_addr { s6_addr: [0; 16] }, // src IP
162	                    ipi6_ifindex: 0,                                // zone id
163	                },
164	            }),
165	        }
166	    }
167	
168	    fn into_address(&self) -> SocketAddr {
169	        match self {
170	            LinuxEndpoint::V4(EndpointV4 { ref dst, .. }) => {
171	                SocketAddr::V4(SocketAddrV4::new(
172	                    u32::from_be(dst.sin_addr.s_addr).into(), // IPv4 addr
173	                    u16::from_be(dst.sin_port),               // convert back to native byte-order
174	                ))
175	            }
176	            LinuxEndpoint::V6(EndpointV6 { ref dst, .. }) => SocketAddr::V6(SocketAddrV6::new(
177	                u128::from_ne_bytes(dst.sin6_addr.s6_addr).into(), // IPv6 addr
178	                u16::from_be(dst.sin6_port), // convert back to native byte-order
179	                dst.sin6_flowinfo,
180	                dst.sin6_scope_id,
181	            )),
182	        }
183	    }
184	
185	    fn clear_src(&mut self) {
186	        match self {
187	            LinuxEndpoint::V4(EndpointV4 { ref mut info, .. }) => {
188	                info.ipi_ifindex = 0;
189	                info.ipi_spec_dst = libc::in_addr { s_addr: 0 };
190	            }
191	            LinuxEndpoint::V6(EndpointV6 { ref mut info, .. }) => {
192	                info.ipi6_addr = libc::in6_addr { s6_addr: [0; 16] };
193	                info.ipi6_ifindex = 0;
194	            }
195	        };
196	    }
197	}
