199	impl LinuxUDPReader {
200	    fn read6(fd: RawFd, buf: &mut [u8]) -> Result<(usize, LinuxEndpoint), io::Error> {
201	        log::trace!(
202	            "receive IPv6 packet (block), (fd {}, max-len {})",
203	            fd,
204	            buf.len()
205	        );
206	
207	        debug_assert!(!buf.is_empty(), "reading into empty buffer (will fail)");
208	
209	        let mut iovs: [libc::iovec; 1] = [libc::iovec {
210	            iov_base: buf.as_mut_ptr() as *mut core::ffi::c_void,
211	            iov_len: buf.len(),
212	        }];
213	        let mut src: libc::sockaddr_in6 = unsafe { mem::MaybeUninit::uninit().assume_init() };
214	        let mut control: ControlHeaderV6 = unsafe { mem::MaybeUninit::uninit().assume_init() };
215	        let mut hdr = libc::msghdr {
216	            msg_name: safe_cast(&mut src),
217	            msg_namelen: mem::size_of_val(&src) as u32,
218	            msg_iov: iovs.as_mut_ptr(),
219	            msg_iovlen: iovs.len(),
220	            msg_control: safe_cast(&mut control),
221	            msg_controllen: mem::size_of_val(&control),
222	            msg_flags: 0,
223	        };
224	
225	        debug_assert!(
226	            hdr.msg_controllen
227	                >= mem::size_of::<libc::cmsghdr>() + mem::size_of::<libc::in6_pktinfo>(),
228	        );
229	
230	        let len = unsafe { libc::recvmsg(fd, &mut hdr as *mut libc::msghdr, 0) };
231	
232	        if len <= 0 {
233	            // TODO: FIX!
234	            return Err(io::Error::new(
235	                io::ErrorKind::NotConnected,
236	                format!(
237	                    "failed to receive (len = {}, fd = {}, errno = {})",
238	                    len,
239	                    fd,
240	                    errno()
241	                ),
242	            ));
243	        }
244	
245	        Ok((
246	            len.try_into().unwrap(),
247	            LinuxEndpoint::V6(EndpointV6 {
248	                info: control.info, // save pktinfo (sticky source)
249	                dst: src,           // our future destination is the source address
250	            }),
251	        ))
252	    }
253	
